/* ONE PALETTE ANSWER PER PICTURE, PER RUN (speed625). step(d,n,w) is the palette
   step (snapToPalette with the run's palette); what comes back does the same
   thing, but a second call on the same bytes (the first n*4, with the same n
   and row width w) gets the first call's answer - the cells written into d
   and a copy of its counts - without running the step again. The step is a
   function of those bytes, n, w and the palette, and one of these lives for
   one picture with one palette (the worker makes one per message), so the
   answer is the same either way. Patch622's palette guard snapped the whole
   picture 4 to 8 times per picture and half of those were bytes it had
   already snapped; the worker then snapped the final cells, which were
   always the guard's last cells, once more. A hash finds the candidate and
   the bytes are compared in full before an answer is reused. */
function snapOnce(step){
  const memo=new Map();
  return function(d,n,w){
    const len=n*4;
    let h=0x811c9dc5;
    for(let i=0;i<len;i++) h=Math.imul(h^d[i],16777619);
    const key=h+","+n+","+w, list=memo.get(key);
    if(list) for(const e of list){
      let same=true;
      for(let i=0;i<len;i++) if(e.inp[i]!==d[i]){ same=false; break; }
      if(same){ d.set(e.out); return Object.assign({},e.res); }
    }
    const inp=new Uint8Array(len); for(let i=0;i<len;i++) inp[i]=d[i];
    const res=step(d,n,w);
    const out=new Uint8Array(len); for(let i=0;i<len;i++) out[i]=d[i];
    const e={inp:inp, out:out, res:Object.assign({},res)};
    if(list) list.push(e); else memo.set(key,[e]);
    return res;
  };
}
